#!/usr/bin/env python3
"""Build an offline visual comparison using actual saved game captures."""
from pathlib import Path
import json, re, os
os.chdir(Path(__file__).resolve().parents[1])
r=Path('docs/reports/canyon-reference-match')
geometry_log=(r/'geometry-tests.log').read_text()
g=re.search(r'GEOMETRY (.*)',geometry_log)
geometry=dict(re.findall(r'(\w+)=([^\s]+)',g.group(1))) if g else {}
checks={}
for n in ['geometry-tests','graphics-tests','occlusion-tests','gameplay-tests']:
 t=(r/f'{n}.log').read_text() if (r/f'{n}.log').exists() else ''
 checks[n]='PASS' if ('PASS' in t or '100% tests passed' in t) and 'FAIL' not in t else 'pending'
benchmark={};render={}
for mode in ['legacy','matched']:
 p=r/f'benchmark-{mode}.log'
 if p.exists():
  t=p.read_text();m=re.search(r'BENCHMARK (.*)',t);v=re.search(r'CANYON_RENDER: (.*)',t)
  if m:benchmark[mode]=dict(re.findall(r'(\w+)=([^\s]+)',m.group(1)))
  if v:render[mode]=dict(re.findall(r'(\w+)=([^\s]+)',v.group(1)))
if len(benchmark)==2:
 for k in ['seed','resolution','frames','max_projectiles','min_active_enemies','min_active_projectiles','kills','max_chain_depth','suppressed']:
  assert benchmark['legacy'][k]==benchmark['matched'][k],k
measurements={'base_commit':'32fa160','working_tree_when_prepared':'uncommitted','geometry':geometry,'checks':checks,'benchmark':benchmark,'render':render,'benchmark_scope':'One paired 240-frame native stress run, original legacy versus current matched treatment, same final executable and assets. Not a repeated statistical comparison or ordinary-play FPS.','capture':{'zoom_percent':160,'fov':45,'projection':'perspective','resolution':[1440,900],'seed':1866,'frame':120},'remaining':['Exact pixel correspondence is not established: the concept has an unknown seed/layout and hand-directed object arrangements.','Canonical collision volumes remain the original taller terrain; visible and physical rock profiles are intentionally separate.'],'verified':all(v=='PASS' for v in checks.values())}
(r/'measurements.json').write_text(json.dumps(measurements,indent=2)+'\n')
css=Path('docs/reports/canyon-terraces/index.html').read_text().split('<style>')[1].split('</style>')[0]
css+=' .pair{display:grid;grid-template-columns:1fr 1fr;gap:16px}.pair img{width:100%;height:auto;display:block}.pair figure{margin:0}.pair figcaption{padding:10px 0;color:var(--muted)}@media(max-width:700px){.pair{grid-template-columns:1fr}}'
h='''<!doctype html><html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>DeathWard · Reference matching pass</title><style>'''+css+'''</style><main><p class="note">Archived committed pass 09cd526. See the <a href="../canyon-composition/index.html">new contour correction report</a> for current captures, checks and remaining visual gaps.</p><div class="eyebrow">DeathWard · Reference matching pass · November 2026</div><h1>From continuous terraces<br>to sandstone formations.</h1><p class="lead">A further visual pass against the supplied concept: shorter geological blocks, low saddles, faceted edges, boulders, warm sandstone and existing native foliage. All game images below are native captures, with no painted-over geometry or post-capture recoloring.</p><p class="note">Camera remains at 160% zoom, perspective / 45° FOV. The concept's seed and exact room position are unknown, so this is a visual-characteristic comparison rather than proof of identical scene layout.</p><h2>Target and current game</h2>'''
for capture,title in [('final-works','Open combat room with sandstone outcrops'),('final-combat','Connected trail room'),('reference-view','Quiet room and surrounding landscape'),('power-view','Power room: open combat floor and short cliffs')]:
 h+=f'''<h3>{title}</h3><div class="pair"><figure><a href="target.png"><img src="target.png" alt="Supplied target concept"></a><figcaption>Supplied target.</figcaption></figure><figure><a href="{capture}.png"><img src="{capture}.png" alt="Actual current game at 160 percent zoom"></a><figcaption>Current game · <a href="{capture}.png">Full PNG</a> · <a href="{capture}.log">Capture log</a></figcaption></figure></div>'''
h+='''<h2>Geometry without decoration</h2><p>The same Works scene with all decoration densities set to zero. Story/gameplay props remain; cliff geometry is identical to the dressed version.</p><a href="geometry-only.png"><img class="reference" src="geometry-only.png" alt="Actual undecorated cliff geometry"></a><h2>Before and after, same seeded scenes</h2>'''
for n in ['combat','works']:
 h+=f'''<article><h3>{n.capitalize()}</h3><div class="compare" style="--split:50%"><img src="final-{n}.png" width="1440" height="900" alt="Reference-matching pass"><div class="before"><img src="before-{n}.png" width="1440" height="900" alt="Previous extruded cliffs"></div><span class="old">Previous pass</span><span class="new">Current pass</span><div class="divider"></div></div><label class="slider">Compare <input type="range" min="0" max="100" value="50" aria-label="Compare {n}"></label></article>'''
h+='''<h2>What changed</h2><ul><li><b>Geological patches:</b> jittered, seeded cells create individual mesas separated by lower saddles. They limit the terrace profile locally, breaking long upper bands into shorter formations.</li><li><b>Cliff proportions:</b> lower initial ledges, narrower variable shelves and broader short chamfers. Walls remain steep; caps remain broad and nearly horizontal. Coarse cap planes align to three source cells (3.75 m), so their fine internal triangles shade as larger faces. The canonical floor-contact contour is retained.</li><li><b>Detached outcrops:</b> cap height follows a restrained part of the original rock's local relief, producing angular boulders rather than uniformly flat-topped pillars.</li><li><b>Materials:</b> warmer floor and sandstone palettes, coherent cap-facet variation, and a local warm sand-bounce approximation on shadowed cliff faces. The shared lighting system and post-processing are unchanged.</li><li><b>Dressing:</b> native grass tufts shaded gold, pointed native desert leaves shaded green, leafy bushes, sparse desert trees on supported upper terrain, small rock/gravel clusters and occasional flowering cacti near suitable room edges. Combat centers, roads and sockets stay reserved.</li><li><b>Flowering cactus:</b> original Western Cactus_05 mesh, with the original red blossom geometry/UVs from Cactus_10 attached at its three tips. The original cactus variants remain available. No replacement texture or generated raster asset. This is a separate FlowerCactus asset; both original cactus models remain unchanged.</li><li><b>Bounds and readability:</b> exact triangle-to-footprint clipping rejects even thin ledges missed by sample grids; a hard 2,200 cosmetic-instance limit, including gravel members; stable density subsets; tree support tests use roots rather than the overhanging canopy. Picking ignores cosmetic props, while whole-object occlusion still fades obstructing geometry.</li></ul>
<h2>Actual native asset previews</h2><p>The previews use original source texture colors and normalized display scales. In-game grass/agave palettes and actual model sizes are shown in the game captures above.</p><a href="selected-native-models.png"><img class="reference" src="selected-native-models.png" alt="Selected native cactus, foliage and tree models"></a><details><summary>Foliage library surveyed before selection</summary><img class="reference" src="foliage-library.png" alt="Eight native foliage variants"></details><details><summary>All 15 original Western cactus variants</summary><img class="reference" src="cactus-library.png" alt="Fifteen native cactus models"></details>
<h2>Validation</h2><div class="scroll"><table><tr><th>Suite</th><th>Status</th><th>Evidence</th></tr>'''
for n,status in checks.items():h+=f'<tr><td>{n}</td><td>{status}</td><td><a href="{n}.log">Log</a></td></tr>'
h+='''</table></div><p>Geometry checks cover 12 maps, all river categories, repeated seed output, unchanged canonical hashes and collision/trace samples, supported vegetation, clear road shoulders and rollback. Graphics checks cover five seeds and both themes, actual mesh/ray agreement, flat cactus support, density/resource behavior and materials. Occlusion checks exercise whole-object fading, enemy outlines and actual aiming/fire. Four fresh gameplay suites cover roads, rivers, generated floors and room graphs. The earlier full floor-progression run remains in the archived correction report; its gameplay code is unchanged.</p>'''
h+='<pre>'+json.dumps(geometry,indent=2)+'</pre>'
h+='''<h2>Performance observation</h2><p>One paired stress run using the same final executable and asset pack: 240 frames, seed 1866, 1440 × 900. Original legacy terrain versus this pass. The benchmark maintains hundreds of projectiles and is not ordinary gameplay FPS. One pair is insufficient for a general speedup/slowdown claim; WSL timing varies.</p><div class="scroll"><table><tr><th>Metric (ms)</th><th>Legacy</th><th>Current</th><th>Observed change</th></tr>'''
if len(benchmark)==2:
 for k in ['mean_ms','p95_ms','draw_ms','present_ms']:
  a,b=float(benchmark['legacy'][k]),float(benchmark['matched'][k]);h+=f'<tr><td>{k}</td><td>{a:.3f}</td><td>{b:.3f}</td><td>{(b/a-1)*100:+.1f}%</td></tr>'
h+='</table></div>'
for mode,d in render.items():h+=f'<p>{mode}: {d["triangles"]} terrain/underlay triangles, {d["chunks"]} terrain chunks, {d["instances"]} visible-density scenery instances.</p>'
h+='''<p><a href="benchmark-legacy.log">Legacy run</a> · <a href="benchmark-matched.log">Current run</a> · <a href="measurements.json">Parsed measurements</a> · <a href="native-build.log">Native build</a></p>
<h2>Configuration and reversibility</h2><p><code>assets/visual/canyon.cfg</code> controls heights, terrace count/width, variation, dressing densities and budgets. Runtime copy: <code>build/assets/visual/canyon.cfg</code>. Restart after editing. <code>enabled 0</code> restores the original tall canyon and original dressing path. Seeded room connectivity, collision, enemy AI, projectiles, UI and camera code are unchanged. The enlarged asset library is packaged; normal game builds do not need Blender or the Unity project.</p><pre>./build/deathward --expedition --theme canyon --style original

# Original terrain and decoration
DEATHWARD_CANYON_CONFIG=assets/visual/canyon-legacy.cfg ./build/deathward</pre>
<h2>Remaining differences</h2><p>This pass is substantially closer in surface orientation, silhouette, color and foliage, but is not a pixel-identical reproduction. The concept has an unknown room seed and deliberately arranged individual rocks and plants. Generated boundary sections can still be more regular, and some boulders more angular, than the reference. Original physical rock volumes remain taller than the visible terrain, as required by preserving gameplay collision. WASM checks remain waived.</p><p>Changes are in <code>CanyonAppearance.*</code>, <code>CanyonScene.cpp</code>, <code>WesternScene.*</code>, the visual config, the native asset library and its import/bake scripts, and associated tests/documentation. Prior reports are preserved as historical comparisons.</p><p><a href="../canyon-extruded-cliffs/index.html">Previous extrusion report</a> · <a href="../canyon-terraces/index.html">Original slope attempt</a></p></main><script>document.querySelectorAll('.slider input').forEach(e=>e.addEventListener('input',()=>e.closest('article').querySelector('.compare').style.setProperty('--split',e.value+'%')));</script></html>'''
(r/'index.html').write_text(h)
print('Reference matching report built:',checks)
